import{f as i,D as n,c as o,o as r,a5 as t,H as l}from"./chunks/framework.BsEAYNxL.js";const _=JSON.parse('{"title":"电商实战：AIGC 图文生产与 Agent 落地","description":"","frontmatter":{"title":"电商实战：AIGC 图文生产与 Agent 落地","date":"2026-01-21T00:00:00.000Z","categories":"study","tags":["ai-chitchat","diffusion","agent","ecommerce","engineering"],"reading_stats":{"count":567,"minutes":2}},"headers":[],"relativePath":"ai-chitchat/03-ecommerce-practice.md","filePath":"ai-chitchat/03-ecommerce-practice.md","lastUpdated":1769663832000}'),s={name:"ai-chitchat/03-ecommerce-practice.md"};function c(p,a,m,g,h,u){const e=n("InkMermaidBlock");return r(),o("div",null,[a[0]||(a[0]=t('<p>如果说原理部分更多是“知道它为什么看起来聪明”，那落地部分就是“接受它默认不可靠”，然后用工程机制把它变得可控。</p><p>在电商里，难点往往不在“能不能生成”，而在“能不能稳定生成同一种风格、同一种口径、同一种约束”。</p><h2 id="_1-图像篇-从-生成-走向-编辑" tabindex="-1">1. 图像篇：从“生成”走向“编辑” <a class="header-anchor" href="#_1-图像篇-从-生成-走向-编辑" aria-label="Permalink to &quot;1. 图像篇：从“生成”走向“编辑”&quot;">​</a></h2><h3 id="_1-1-mask-inpaint-与-outpaint" tabindex="-1">1.1 Mask, Inpaint 与 Outpaint <a class="header-anchor" href="#_1-1-mask-inpaint-与-outpaint" aria-label="Permalink to &quot;1.1 Mask, Inpaint 与 Outpaint&quot;">​</a></h3><p>在工程上，Mask 不是一个像素图那么简单，它是一个契约：哪些区域允许改，哪些区域必须保持。</p><ul><li><strong>Inpaint（修复）</strong>：在原图上“补”。常见翻车点是边界不一致、语义漂移。</li><li><strong>Outpaint（扩展）</strong>：把画面“扩出去”。常见翻车点是纹理、背景不连贯。</li></ul><h3 id="_1-2-结构化生成-figma-→-json-→-sd" tabindex="-1">1.2 结构化生成：Figma → JSON → SD <a class="header-anchor" href="#_1-2-结构化生成-figma-→-json-→-sd" aria-label="Permalink to &quot;1.2 结构化生成：Figma → JSON → SD&quot;">​</a></h3><p>我做过一类相对工程化的尝试：把“设计稿”拆成结构化模板，让生成模型只负责填坑位。</p><ul><li>输入：Figma 设计稿</li><li>中间表示：模板 JSON（组件、坐标、坑位、约束）</li><li>输出：由 SD 生成图/文素材，再回填到模板里</li></ul><p>这条链路的价值在于：你把“可控性”从 Prompt 转移到“结构与约束”上——工程上更容易治理。</p><h3 id="_1-3-虚拟试衣-工程拼装管线" tabindex="-1">1.3 虚拟试衣：工程拼装管线 <a class="header-anchor" href="#_1-3-虚拟试衣-工程拼装管线" aria-label="Permalink to &quot;1.3 虚拟试衣：工程拼装管线&quot;">​</a></h3><p>虚拟试衣是另一类“生成 + 约束”的问题。一个常见的工程拼装思路是：先把几何/姿态约束做出来，再把生成当作“渲染器”。</p>',12)),l(e,{codeBase64:""}),a[1]||(a[1]=t('<h2 id="_2-文本篇-agent-落地实战" tabindex="-1">2. 文本篇：Agent 落地实战 <a class="header-anchor" href="#_2-文本篇-agent-落地实战" aria-label="Permalink to &quot;2. 文本篇：Agent 落地实战&quot;">​</a></h2><h3 id="_2-1-prompt-与-a2ui" tabindex="-1">2.1 Prompt 与 A2UI <a class="header-anchor" href="#_2-1-prompt-与-a2ui" aria-label="Permalink to &quot;2.1 Prompt 与 A2UI&quot;">​</a></h3><p>我写 Prompt 的习惯是把它当作“接口契约”：输入是什么、输出是什么（Schema）、失败怎么处理。</p><p><strong>A2UI</strong> 是一类更偏“把语言变成交付物”的尝试：</p><ul><li>用户自然语言 -&gt; Agent 拆解 -&gt; JSON (Schema 固定) -&gt; XUI 渲染 -&gt; 最终产物。</li><li>关键点：JSON 是工程的地基，让你能做校验、回归、Diff。</li></ul><h2 id="_3-治理与兜底-从个人爽感到团队可控" tabindex="-1">3. 治理与兜底：从个人爽感到团队可控 <a class="header-anchor" href="#_3-治理与兜底-从个人爽感到团队可控" aria-label="Permalink to &quot;3. 治理与兜底：从个人爽感到团队可控&quot;">​</a></h2><p>2025 大概率是 Agent 元年，但难点不会在模型，而在治理。</p><ul><li><strong>成本</strong>：Token、延迟、工具调用次数。</li><li><strong>风险</strong>：合规、版本漂移、依赖锁定。</li><li><strong>兜底</strong>：降级、回滚、人工介入。</li></ul><p>工程人的关键觉悟：<strong>把模型能力当作一个不稳定依赖</strong>。你需要 trace、需要测试、需要对账。</p>',9))])}const k=i(s,[["render",c]]);export{_ as __pageData,k as default};
